sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
// Parse the new value as a Date
  var inputDate = new Date(newValue);

  // Get today's date and zero out the time portion
  var today = new Date();
  today.setHours(0, 0, 0, 0);

  // Check if input date is before today
  if (inputDate < today) {
    g_form.showFieldMsg('departing_on', "Departure Date cannot be earlier than today.", "error");

  }
else { g_form.showFieldMsg('departing_on',true); }

}
